SELECT 
    MIN(date_time) as min_datetime,
    MAX(date_time) as max_datetime
FROM t_amz_transaction_report
WHERE amazonauthid = #{amazonauthid}
AND marketplaceid = #{marketplaceid}
AND DATE(date_time) >= #{startDate}
AND DATE(date_time) <= #{endDate}

SELECT COUNT(*)
FROM t_amz_transaction_report
WHERE amazonauthid = #{amazonauthid}
AND marketplaceid = #{marketplaceid}
AND DATE(date_time) >= #{startDate}
AND DATE(date_time) <= #{endDate}

